import {situations,goals,homeSections,guideControls,facetPanel,discoveryFilter,inferSituations} from './discovery.js?v=20261107-9';
import {renderMedia,disposeMedia} from './media.js?v=20261107-9';
import { makeDeck, kitItemLabel } from './study.js?v=20261107-9';
import { normalize, filterProducts, money, safeUrl } from './core.js?v=20261107-9';
const $ = id => document.getElementById(id);
const html = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category='', studyIndex=0, studyRevealed=false;
let returnKit=null;
let directResults=false;
let selectedHairTypes=new Set(),selectedProductTypes=new Set(),selectedSituations=new Set(),selectedGoal='',guideDescription='',guideManual=false;
let catalog, page='catalogo', need='', query='', line='', type='', sort='name', selected=new Set(), currentProduct=null, detailTab='overview', installPrompt=null;
const storageKey='dal-consultor-v1';
let personal={favorites:[],notes:{}};
try { const stored=JSON.parse(localStorage.getItem(storageKey)); if(stored && Array.isArray(stored.favorites) && stored.notes && typeof stored.notes==='object') personal=stored; } catch {}
personal.study??={};
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(personal));return true;}catch{toast('Não foi possível salvar no aparelho. Exporte uma cópia das anotações.');return false;}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5000);}
function favorite(id){if(!catalog.products.some(p=>p.id===id))return;personal.favorites=personal.favorites.includes(id)?personal.favorites.filter(x=>x!==id):[...personal.favorites,id];persist();renderCards();if(currentProduct?.id===id)renderDetail();}
const needLabels=['Hidratação','Nutrição','Reconstrução','Cachos','Frizz','Oleosidade','Loiros','Fortalecimento','Perfumaria'];
function route(){const [path,params='']=location.hash.slice(1).split('?');const [name,part='']=path.split('/');page=['catalogo','linhas','kits','estudar','pesquisa','favoritos','guia','offline','empresa','videos'].includes(name)?name:'catalogo';directResults=name==='guia'&&new URLSearchParams(params).get('direto')==='1';const value=decodeURIComponent(part);if(page==='catalogo'){category=value;line='';}else if(page==='linhas'){line=value;category=new URLSearchParams(params).get('categoria')||'';}else if(page==='kits'){line=value;category='';}else if(page==='estudar'){line=value;category=new URLSearchParams(params).get('categoria')||'';studyIndex=0;studyRevealed=false;}else{category='';line='';}document.querySelectorAll('[data-page]').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(page==='guia'){const state=new URLSearchParams(params);selectedSituations=new Set(state.getAll('situacao'));selectedGoal=state.get('resultado')||'';guideDescription=state.get('q')||'';guideManual=false;query='';need='';category='';line='';type='';if(directResults){selectedHairTypes.clear();selectedProductTypes.clear();sort='name';}}$('line-filter').value=line;$('category-filter').value=category;render();if(page==='pesquisa')setTimeout(()=>$('search').focus(),80);}
function render(){if(!catalog)return;disposeMedia();const browsing=['pesquisa','favoritos','kits','guia'].includes(page)||(page==='catalogo'&&category)||(page==='linhas'&&line);$('hero').hidden=true;$('study-browser').hidden=!browsing;$('catalog-controls').hidden=!browsing;$('results-heading').hidden=!browsing;$('products').hidden=!browsing;$('extra-content').hidden=!['offline','estudar','empresa','videos'].includes(page);$('download-top').hidden=page==='offline';$('nav-count').textContent=catalog.products.length;$('favorite-count').textContent=personal.favorites.length;
 const titles={catalogo:category||'Estude por categoria',linhas:line?'Linha '+line:'Linhas de produtos',kits:line?'Kits da linha '+line:'Kits e seus componentes',estudar:'Revisar o que aprendeu',pesquisa:'Pesquisar produtos e ativos',favoritos:'Meus favoritos',guia:'Cada necessidade, um cuidado',offline:'Seu material de estudo offline',videos:'Demonstrações e resultados',empresa:'Sobre a Dal Cotone'};
 $('page-title').textContent=titles[page];$('page-subtitle').textContent=page==='kits'?'Todos os kits conferidos, com itens, volumes e pendências identificados.':page==='catalogo'&&!category?'Escolha o tratamento e depois a linha que quer conhecer.':page==='linhas'&&!line?'Abra uma linha para estudar seus kits e produtos avulsos.':'O que faz, quando usar, ativos e modo de uso — em uma ficha simples.';
 $('page-eyebrow').textContent='SUA BIBLIOTECA DE PRODUTOS';$('catalog-footnote').textContent='As fichas reúnem páginas oficiais e o catálogo profissional 2025. Campos não publicados ficam a confirmar. Ativos divulgados não são a lista completa de ingredientes.';
 $('study-browser').classList.toggle('direct-results',directResults);if(directResults){const topic=situations.find(s=>selectedSituations.has(s.id))||goals.find(g=>g.id===selectedGoal);$('page-title').textContent=topic?.name||'Produtos para este cuidado';$('page-subtitle').textContent='Todos os produtos e kits com indicações relacionadas a este cuidado. Abra um item para conferir sua função e como usar.';$('catalog-controls').hidden=true;}renderOrganization();if(page==='guia')renderGuide();if(browsing)renderCards();else if(page==='offline')renderOffline();else if(page==='estudar')renderStudy();else if(page==='empresa')renderCompany();else if(page==='videos')renderMedia($('extra-content'),catalog,toast);
}
function renderOrganization(){const node=$('organization');node.hidden=['pesquisa','favoritos','guia','offline','empresa','videos'].includes(page);const lineCard=l=>`<a class="line-card" href="#linhas/${encodeURIComponent(l.name)}${category?'?categoria='+encodeURIComponent(category):''}"><span class="eyebrow">LINHA</span><h3>${html(l.name)}</h3><p>${l.productIds.length} itens · ${l.kitIds.length} kits</p><small>${html(l.categories.slice(0,3).join(' · '))}</small><span class="line-arrow">→</span></a>`;
 if(page==='catalogo'&&!category){node.innerHTML=homeSections(catalog)+`<h3 class="organization-title">Explorar todas as categorias</h3><div class="category-grid">${catalog.categories.map(c=>`<a class="category-card" href="#catalogo/${encodeURIComponent(c.name)}"><span>◇</span><h3>${html(c.name)}</h3><small>${c.count} itens</small><b>→</b></a>`).join('')}</div>`;}
 else if(page==='catalogo'){const lines=catalog.lines.filter(l=>l.categories.includes(category));node.innerHTML=`<nav class="breadcrumbs"><a href="#catalogo">Categorias</a><span>›</span><b>${html(category)}</b></nav><h3 class="organization-title">Linhas nesta categoria</h3><div class="line-grid">${lines.map(lineCard).join('')}</div><h3 class="organization-title">Produtos e kits de ${html(category)}</h3>`;}
 else if(page==='linhas'&&!line){node.innerHTML=`<div class="line-grid">${catalog.lines.map(lineCard).join('')}</div>`;}
 else if(page==='linhas'){node.innerHTML=`<nav class="breadcrumbs"><a href="#linhas">Linhas</a><span>›</span><b>${html(line)}</b>${category?`<span>›</span><a href="#catalogo/${encodeURIComponent(category)}">${html(category)}</a>`:''}</nav>${lineApproach(line)}<div class="line-actions"><a class="button light small" href="#kits/${encodeURIComponent(line)}">Ver kits e componentes</a><a class="button dark small" href="#estudar/${encodeURIComponent(line)}">Revisar esta linha</a></div>`;}
 else if(page==='kits'){node.innerHTML=`<p class="study-hint">Abra um kit para ver os componentes. Os volumes omitidos na fonte ficam sinalizados.</p>`;}
 else if(page==='estudar'){node.innerHTML=`<label class="study-filter">Estudar uma linha <select id="study-line"><option value="">Todas as linhas</option>${catalog.lines.map(l=>`<option value="${html(l.name)}" ${l.name===line?'selected':''}>${html(l.name)}</option>`).join('')}</select></label>`;}
}
function lineApproach(name){const data=catalog.lines.find(l=>l.name===name)?.salonApproach;if(!data)return '';return `<details class="presentation-panel line-presentation"><summary class="line-presentation-summary">Apresentação profissional · ${html(name)}<small>Diagnóstico, argumento técnico, demonstração e objeções</small></summary><div class="presentation-heading"><h3>Conduza a conversa pela necessidade do salão</h3><button class="button light small" data-copy-script="line-script">Copiar roteiro</button></div><div id="line-script"><div class="presentation-step"><span>Abra a conversa</span><p>${html(data.discoveryQuestion)}</p></div><div class="presentation-step"><span>Apresente a proposta</span><p>${html(data['30secTalkTrack'])}</p></div><div class="presentation-step"><span>Explique o fundamento técnico</span><p>${html(data.technicalReason)}</p></div><div class="presentation-step"><span>Planeje a demonstração</span><p>${html(data.demonstrationPlan)}</p></div><div class="presentation-step"><span>Responda à objeção</span><p>${html(data.realObjectionReply)}</p></div><div class="presentation-step"><span>Avance com um próximo passo concreto</span><p>${html(data.closingStep)}</p></div></div><p class="details-meta">${html(data.avoidClaims)}</p></details>`;}

function renderStudy(){const deck=makeDeck(catalog.products,{line,category});if(!deck.length){$('extra-content').innerHTML='<div class="empty"><h3>Revisão ainda sem informações suficientes</h3><p>Estude a ficha da linha e confira os campos pendentes.</p></div>';return;}studyIndex=Math.min(studyIndex,deck.length-1);const card=deck[studyIndex];$('extra-content').innerHTML=`<section class="study-card"><div class="study-card-meta"><span>${html(card.line)} · ${html(card.topic)}</span><b>${studyIndex+1} / ${deck.length}</b></div><h3>${html(card.question)}</h3>${studyRevealed?`<p class="study-answer">${html(card.answer)}</p><p class="details-meta">Resumo da ficha e das fontes indicadas. Campos não confirmados não viram perguntas.</p><div class="line-actions"><button class="button light" data-study-mark="review">Quero revisar</button><button class="button dark" data-study-mark="known">Já sei →</button></div>`:'<button class="button dark" id="reveal-study">Mostrar resposta</button>'}<div class="study-card-bottom"><button class="text-button" data-open="${card.productId}">Abrir ficha completa</button><span>${personal.study[card.id]==='known'?'✓ Marcado como aprendido':personal.study[card.id]==='review'?'↻ Para revisar':''}</span><button class="text-button" id="next-study">Próximo →</button></div></section>`;}
function photo(p,detail=false){const componentIds=p.type==='Kits'?[...new Set((p.kitItems||[]).map(i=>i.productId).filter(Boolean))]:[];const components=componentIds.map(id=>catalog.products.find(q=>q.id===id)).filter(q=>q?.imageUrl?.startsWith('/assets/')).slice(0,4);const fallback=components.length?`<div class="component-photo-grid">${components.map(q=>`<img src="${html(safeUrl(q.imageUrl))}" alt="${html(q.name)}">`).join('')}</div><small>Fotos dos componentes documentados · consulte a versão do kit</small>`:`<span>dc</span><small>${p.imageUrl?'Foto indisponível neste momento':'Foto oficial ainda não localizada'}</small>`;return `<img src="${html(safeUrl(p.imageUrl))}" alt="${html(p.imageContext||p.name)}" ${detail?'':'loading="lazy"'} referrerpolicy="no-referrer"><div class="photo-placeholder">${fallback}</div>`;}

function handleImages(root=document){root.querySelectorAll('img').forEach(img=>{if(!img.getAttribute('src'))img.hidden=true;else if(img.complete&&img.naturalWidth===0)img.hidden=true;img.addEventListener('error',()=>{img.hidden=true;},{once:true});});}
function renderCards(){$('favorite-count').textContent=personal.favorites.length;const favoritesOnly=page==='favoritos';let products=filterProducts(catalog.products,{query,need,category,line,type:page==='kits'?'Kits':type,sort,favorites:favoritesOnly?personal.favorites:null});products=discoveryFilter(products,{selectedHairTypes:[...selectedHairTypes],selectedTypes:[...selectedProductTypes],selectedSituations:page==='guia'?[...selectedSituations]:[],selectedGoal:page==='guia'?selectedGoal:'',description:page==='guia'&&!guideManual?guideDescription:''});if(sort!=='name')products=filterProducts(products,{sort});$('study-filter-panel').innerHTML=facetPanel(catalog.products,{selectedHairTypes:[...selectedHairTypes],selectedTypes:[...selectedProductTypes],open:innerWidth>=900});$('result-count').textContent=`${products.length} ${products.length===1?'produto encontrado':'produtos encontrados'}`;$('study-filter-panel').hidden=directResults;$('reset-filters').hidden=directResults||!(query||need||line||type||selectedHairTypes.size||selectedProductTypes.size||selectedSituations.size||selectedGoal||guideDescription);$('search').value=query;$('clear-search').hidden=!query;
 $('need-chips').innerHTML=['Todos',...needLabels].map(n=>`<button class="chip ${need===(n==='Todos'?'':n)?'active':''}" data-need="${html(n==='Todos'?'':n)}" aria-pressed="${need===(n==='Todos'?'':n)}">${html(n)}</button>`).join('');
 if(page==='linhas')products.sort((a,b)=>(a.type==='Kits'?1:0)-(b.type==='Kits'?1:0)||a.name.localeCompare(b.name,'pt-BR'));
 $('products').innerHTML=products.length?products.map((p,index)=>`${page==='linhas'&&(index===0||(products[index-1].type==='Kits')!==(p.type==='Kits'))?`<h3 class="card-group-label">${p.type==='Kits'?'Kits e componentes':'Produtos da linha'}</h3>`:''}<article class="product-card"><div class="product-photo" data-open="${p.id}" role="button" tabindex="0" aria-label="Ver ${html(p.name)}"><span class="line-badge">${html(p.line)}</span><button class="favorite ${personal.favorites.includes(p.id)?'on':''}" data-favorite="${p.id}" aria-label="${personal.favorites.includes(p.id)?'Remover dos favoritos':'Favoritar'}: ${html(p.name)}" aria-pressed="${personal.favorites.includes(p.id)}">${personal.favorites.includes(p.id)?'♥':'♡'}</button>${photo(p)}</div><div class="card-info"><span class="card-category">${html(p.type)}</span><h3 class="card-title"><button class="card-open" data-open="${p.id}">${html(p.name)}</button></h3><p class="card-summary">${html(p.benefits?.slice(0,2).join(' · ')||'Consulte a ficha e a fonte oficial.')}</p><div class="card-tags">${(p.categories||[]).slice(0,2).map(n=>`<span class="tag">${html(n)}</span>`).join('')}${p.sourceKind==='consultor'?'<span class="tag">Informado pelo consultor</span>':''}</div><div class="price-row"><span class="study-open-label">${p.type==='Kits'?'Estudar componentes':'Estudar produto'}</span><button class="card-arrow" data-open="${p.id}" aria-label="Abrir ficha de ${html(p.name)}">↗</button></div></div><label class="compare-label"><input type="checkbox" data-compare="${p.id}" ${selected.has(p.id)?'checked':''}> Comparar produto</label></article>`).join(''):`<div class="empty"><h3>${favoritesOnly?'Seu espaço de favoritos':'Nenhum produto encontrado'}</h3><p>${favoritesOnly?'Toque no coração dos produtos que você quer consultar mais rápido.':'Tente outro nome, ativo ou necessidade, ou limpe os filtros.'}</p><button class="button" data-reset>Limpar filtros</button></div>`;
 handleImages($('products'));renderCompareTray();
}
function reset(){query='';need='';type='';selectedHairTypes.clear();selectedProductTypes.clear();selectedSituations.clear();selectedGoal='';guideDescription='';guideManual=false;if(page==='guia'){saveGuideState();renderGuide();}if(page==='pesquisa'||page==='favoritos'||page==='kits')category='';$('category-filter').value=category;if(page!=='linhas')line='';$('line-filter').value='';$('type-filter').value='';renderCards();}
function renderCompany(){const company=catalog.company;$('extra-content').innerHTML=`<div class="company-intro"><p class="eyebrow">CONHEÇA A MARCA PARA APRESENTAR MELHOR</p><h3>Uma base para sua conversa com novos salões.</h3><p>História e informações institucionais, com fontes para você consultar. O roteiro abaixo pode ser adaptado à sua forma de falar.</p></div><section class="presentation-panel brand-presentation"><div class="presentation-heading"><h3>Uma apresentação da marca</h3><button class="button light small" data-copy-script="brand-script">Copiar apresentação</button></div><p class="spoken-script" id="brand-script">${html(company.brandApproach.presentation)}</p><h4>Por que esses pontos importam na conversa?</h4><div class="brand-arguments">${company.brandApproach.valuePoints.map(v=>`<details><summary>${html(v.title)}</summary><p>${html(v.meaning)}</p><blockquote>${html(v.say)}</blockquote><p class="details-meta">${html(v.limit)}</p><a class="source-link" href="${html(safeUrl(v.sourceUrl))}" target="_blank" rel="noopener noreferrer">Base da informação ↗</a></details>`).join('')}</div><div class="presentation-step"><span>Para passar da marca aos produtos</span><p>${html(company.brandApproach.transition)}</p></div><div class="presentation-step"><span>Para continuar sem pressionar</span><p>${html(company.brandApproach.close)}</p></div><small>${html(company.brandApproach.tone)}</small></section><div class="company-grid">${company.facts.map(f=>`<article class="company-fact"><span class="eyebrow">${html(f.label)}</span><h3>${html(f.value)}</h3><p>${html(f.detail)}</p><a class="source-link" href="${html(safeUrl(f.sourceUrl))}" target="_blank" rel="noopener noreferrer">Fonte oficial ↗</a></article>`).join('')}</div><section class="company-pitch"><h3>Como começar a apresentação</h3><p id="company-pitch-text">${html(company.pitch)}</p><button class="button dark small" id="copy-pitch">Copiar roteiro</button><small>Adapte seu nome e a apresentação à sua relação com o salão.</small></section><section class="company-questions"><h3>Perguntas para conhecer o salão</h3><ol>${company.questions.map(q=>`<li>${html(q)}</li>`).join('')}</ol><a class="button light small" href="#linhas">Conhecer as linhas →</a><a class="button light small" href="#kits">Estudar os kits →</a></section><details class="company-legal"><summary>Dados comerciais publicados</summary><p>${html(company.operator.name)}<br>CNPJ ${html(company.operator.cnpj)}<br>${html(company.operator.address)}</p><a class="source-link" href="${html(safeUrl(company.operator.sourceUrl))}" target="_blank" rel="noopener noreferrer">Consultar dados no site oficial ↗</a></details><p class="details-meta">Informações consultadas em ${catalog.dateLabel}. ${html(company.notes.join(' '))}</p>`;}
function renderGuide(){if(directResults){$('organization').hidden=false;$('organization').innerHTML='<nav class="breadcrumbs"><a href="#catalogo">← Voltar às situações do cabelo</a></nav>';return;}$('organization').hidden=false;$('organization').innerHTML=guideControls({selectedSituations:[...selectedSituations],selectedGoal,description:guideDescription});}
function saveGuideState(){const state=new URLSearchParams();for(const value of selectedSituations)state.append('situacao',value);if(selectedGoal)state.set('resultado',selectedGoal);if(guideDescription&&!guideManual)state.set('q',guideDescription);history.replaceState(null,'','#guia'+(state.size?'?'+state:''));}

function kitContents(p){if(!p.kitItems?.length)return missing('A fonte não apresentou a lista de componentes deste kit.');const statuses={confirmed:'Componentes e volumes confirmados',partial:'Composição documentada · confira as observações da apresentação',unavailable:'Lista ainda não disponível'};return `<p class="kit-status">${html(p.kitReview?.compositionVersion||statuses[p.kitReview?.status]||'Componentes identificados')}</p><ol class="kit-components">${p.kitItems.map(item=>{const ids=item.productId?[item.productId]:(item.candidateProductIds||[]);return `<li><b>${html(kitItemLabel(item))}</b>${!item.productId?'<small>O volume no kit não foi confirmado. As fichas abaixo mostram apresentações disponíveis para consulta.</small>':''}<div class="component-links">${ids.map(id=>{const q=catalog.products.find(q=>q.id===id);return q?`<button class="component-link" data-open="${id}" data-from-kit="${p.id}">${q.imageUrl?`<img src="${html(safeUrl(q.imageUrl))}" alt="" loading="lazy">`:''}<span>${html(q.name)}<small>Abrir ficha completa →</small></span></button>`:'';}).join('')||'<small>Apresentação individual ainda não documentada na fonte.</small>'}</div></li>`;}).join('')}</ol>`;}

function missing(label){return `<p class="missing">${html(label||'Não informado na fonte consultada. Confira o rótulo ou a ficha técnica da marca.')}</p>`;}
function list(items){return Array.isArray(items)&&items.length?`<ul>${items.map(i=>`<li>${html(typeof i==='string'?i:JSON.stringify(i))}</li>`).join('')}</ul>`:missing();}
function openProduct(id,fromKit=null){returnKit=fromKit;currentProduct=catalog.products.find(p=>p.id===id);if(!currentProduct)return;detailTab='overview';renderDetail();if(!$('product-dialog').open)$('product-dialog').showModal();}
function renderDetail(){const p=currentProduct;const favoriteOn=personal.favorites.includes(p.id);const tabs=[['overview','O que faz / quando usar'],...(p.type==='Kits'?[['kit','Componentes do kit']]:[]),['actives','Ativos e funções'],['presentation','Como apresentar'],['technical','Técnico e diferenciais'],['use','Modo de uso'],['composition','Composição'],['notes','Minhas notas']];
 let section='';
 if(detailTab==='overview')section=`${p.description?`<h3>Descrição</h3><p>${html(p.description)}</p>`:''}<h3>O que faz</h3>${list(p.benefits)}<h3>Para qual necessidade</h3>${p.indication?`<p>${html(p.indication)}</p>`:missing()}${p.needs?.length?`<div class="card-tags">${p.needs.map(n=>`<span class="tag">${html(n)}</span>`).join('')}</div>`:''}<h3>Em qual ocasião usar</h3>${p.occasions?.length?list(p.occasions):missing('A ocasião de uso ainda não foi confirmada para esta apresentação.')}${p.type==='Kits'?`<h3>Componentes do kit</h3>${kitContents(p)}`:''}<h3>Apresentação</h3>${p.contents?`<p>${html(p.contents)}</p>`:missing('O conteúdo detalhado da embalagem ou kit não foi localizado na fonte consultada. O volume, quando confirmado, aparece no nome do produto.')}`;
 else if(detailTab==='kit')section=`<h3>O que compõe este kit</h3>${kitContents(p)}<p class="details-meta">${html((p.kitReview?.notes||[]).join(' '))}</p>`;
 else if(detailTab==='actives')section=`<h3>Ativos divulgados e suas funções</h3>${p.activeDetails?.length?`<div class="active-grid">${p.activeDetails.map(a=>`<article class="active-card"><h4>${html(a.name)}</h4><p>${html(a.role||'A fonte não detalha a função individual deste ativo.')}</p>${a.scope==='blend'?'<small>Função atribuída ao conjunto de ativos, não ao ingrediente isolado.</small>':''}${a.sourceUrl?`<a class="source-link" target="_blank" rel="noopener noreferrer" href="${html(safeUrl(a.sourceUrl))}">Fonte da função ↗</a>`:''}</article>`).join('')}</div>`:list(p.actives)}${p.olfactoryNotes?`<h3>Notas olfativas · aroma</h3>${Object.entries(p.olfactoryNotes).map(([group,notes])=>`<h4>${html({topo:'Saída',coracao:'Coração',fundo:'Fundo'}[group]||group)}</h4>${list(Array.isArray(notes)?notes:[notes])}`).join('')}<p class="details-meta">Notas olfativas descrevem o cheiro; não comprovam que esses ingredientes estejam na fórmula.</p>`:''}<p class="details-meta">São os destaques publicados para este produto. A presença de um ativo não informa sua concentração e não representa a lista completa de ingredientes.</p>`;
 else if(detailTab==='presentation'){const a=p.presentation;section=`<section class="presentation-panel product-presentation"><div class="presentation-heading"><div><p class="eyebrow">${html(a.audience)}</p><h3>Como apresentar ${html(p.name)}</h3></div><button class="button light small" data-copy-script="product-script">Copiar apresentação</button></div><div id="product-script"><h4>Objetivo desta conversa</h4><p>${html(a.decisionGoal)}</p><h4>Perguntas que orientam a indicação</h4>${list(a.discoveryQuestions)}<div class="pitch-card"><span class="eyebrow">SUA APRESENTAÇÃO</span><p>${html(a.opening)}</p></div>${a.components?.length?`<h4>O papel de cada componente</h4>${a.components.map(component=>`<article class="objection-card"><b>${html(component.name)}${component.volume?' · '+html(component.volume):' · volume no kit não confirmado'}</b>${component.choices.map(q=>`<p><button class="text-button" data-open="${q.id}" data-from-kit="${p.id}">${html(q.name)} →</button></p><p>${html(q.function||'Função individual não detalhada na fonte.')}</p>${q.actives.length?`<details><summary>Ativos e aplicação desta apresentação</summary>${q.activeDetails?.length?q.activeDetails.map(active=>`<p><b>${html(active.name)}:</b> ${html(active.role||'A fonte não discrimina sua função individual.')}</p>`).join(''):`<p>${html(q.actives.join(', '))}</p>`}${q.use?`<p><b>Aplicação:</b> ${html(q.use)}</p>`:''}</details>`:''}`).join('')}</article>`).join('')}`:''}<h4>O argumento técnico que sustenta a proposta</h4><p>${html(a.technicalReason)}</p>${p.activeDetails?.length?`<details class="pitch-actives"><summary>Explicar todos os ativos divulgados (${p.activeDetails.length})</summary>${p.activeDetails.map(active=>`<article class="active-card"><b>${html(active.name)}</b><p>${html(active.role||'A fonte identifica o ativo, mas não descreve sua função isolada nesta fórmula.')}</p></article>`).join('')}</details>`:''}<h4>Como demonstrar no atendimento</h4><p>${html(a.demonstration.plan)}</p><p><b>O que observar:</b> ${html(a.demonstration.watchFor)}.</p>${a.demonstration.protocol?`<details><summary>Conferir o protocolo desta apresentação</summary><p>${html(a.demonstration.protocol)}</p></details>`:''}<h4>Objeções e respostas</h4>${a.objections.map(o=>`<article class="objection-card"><b>${html(o.question)}</b><p>${html(o.answer)}</p></article>`).join('')}<h4>Próximo passo</h4><p>${html(a.nextStep)}</p></div><p class="details-meta">${html(a.avoidClaims)}</p></section><button class="button light small" data-product-line="${html(p.line)}">Ver estratégia da linha ${html(p.line)} →</button>`;}

 else if(detailTab==='technical')section=`<h3>Ficha técnica</h3><dl class="technical-grid">${[['Linha',p.technical?.line],['Tipo de produto',p.technical?.productType],['Apresentação confirmada',p.technical?.presentation],['pH declarado',p.technical?.declaredPH],['Concentrações dos ativos',p.technical?.concentrations],['Lista INCI completa',p.compositionIsINCI===false?'Composição do site disponível; nomenclatura INCI não conferida':p.inci?'Publicada nesta ficha':'Ainda não capturada nesta revisão']].map(([label,value])=>`<div><dt>${html(label)}</dt><dd>${html(value||'Não informado na fonte')}</dd></div>`).join('')}</dl><h3>Diferenciais para estudar</h3>${p.differentials?.length?p.differentials.map(d=>`<article class="active-card technical-differential"><h4>${html(d.title)}</h4><p>${html(d.text)}</p><small>${html(d.evidence)}</small><a class="source-link" href="${html(safeUrl(d.sourceUrl))}" target="_blank" rel="noopener noreferrer">Fonte ↗</a></article>`).join(''):missing('Os diferenciais técnicos ainda precisam de uma ficha oficial para este item.')}<h3>Como explicar a proposta</h3>${p.commercialSummary?`<p>${html(p.commercialSummary)}</p>`:missing()}<h3>O que muda em relação à mesma linha</h3><div class="technical-related">${catalog.products.filter(q=>q.line===p.line&&q.id!==p.id).slice(0,12).map(q=>`<button class="text-button" data-open="${q.id}">${html(q.name)} →</button>`).join('')||'<p>Não há outra apresentação catalogada nesta linha.</p>'}</div><p class="details-meta">Comparação com concorrentes: não há ensaio comparativo registrado nesta ficha. Os diferenciais descrevem a proposta e os dados da marca; não comprovam que o produto supere todos os concorrentes.</p>`;
 else if(detailTab==='use')section=`<h3>Como usar</h3>${p.use?`<p>${html(p.use)}</p>`:missing()}<p class="details-meta">Resumo da orientação da fonte consultada. Em caso de divergência, confira o rótulo da embalagem que você tem em mãos.</p>`;
 else if(detailTab==='composition'){const statement=p.inci||p.rawSiteComposition;section=`<h3>${p.inci?'Composição declarada':'Como a página descreve a composição'}</h3>${statement?`<p>${html(statement)}</p><p class="details-meta">${html(p.compositionOrigin||(p.compositionKind?.includes('olfactory')?'São notas olfativas; não equivalem à lista de ingredientes.':'A fonte pode destacar ativos ou componentes do kit. Esses destaques não substituem o INCI do rótulo.'))}</p>`:missing('Composição completa ainda não capturada nesta ficha. Consulte a lista de ingredientes da embalagem.')} ${p.notes?.length?`<h3>Observações da fonte</h3>${list(p.notes)}`:''}`;}

 else section=`<h3>Suas anotações</h3><p>Registre suas observações de consulta. Elas ficam somente neste navegador, neste aparelho.</p><label class="sr-only" for="product-note">Anotações sobre ${html(p.name)}</label><textarea id="product-note" class="detail-note" maxlength="10000" placeholder="Ex.: dúvidas para confirmar com a marca, pontos importantes da apresentação…">${html(personal.notes[p.id]||'')}</textarea><p class="save-state" id="note-state">Salvamento automático no aparelho. Exporte uma cópia na aba Offline.</p>`;
 if(detailTab==='composition'&&p.compositionCaptures?.length)section+=p.compositionCaptures.map(c=>`<details class="source-history"><summary>${html(c.label)}</summary><p>${html(c.text)}</p></details>`).join('');
 if(detailTab==='actives'&&p.olfactoryNotesByProduct)section+=`<h3>Pirâmide de cada fragrância do kit</h3>${Object.entries(p.olfactoryNotesByProduct).map(([name,notes])=>`<h4>${html(name)}</h4>${Object.entries(notes).map(([stage,values])=>`<p><b>${html(stage)}:</b> ${html(Array.isArray(values)?values.join(', '):values)}</p>`).join('')}`).join('')}`;
 if(detailTab==='use'&&p.instructionVersions?.length)section+=p.instructionVersions.map(v=>`<details class="source-history"><summary>${html(v.label)}</summary><p>${html(v.text)}</p><p>Orientações de edições diferentes não devem ser combinadas; confira o rótulo atual.</p></details>`).join('');
 if(['technical','composition','use','actives'].includes(detailTab)){
  if(p.sourceDifferences?.length)section+='<aside class="source-difference"><h3>Versões e orientações diferentes</h3>'+p.sourceDifferences.map(d=>'<p>'+html(d.description||d.issue)+'</p>').join('')+'<p>Confira a edição e o rótulo da embalagem antes de aplicar. Os dados de versões diferentes não devem ser combinados.</p></aside>';
  for(const historical of p.historicalFields||[])section+='<details class="source-history"><summary>'+html(historical.source)+' · página '+historical.page+'</summary>'+Object.entries(historical.fields).map(([key,value])=>'<h4>'+html({actives:'Ativos',use:'Modo de uso',indication:'Indicação',components:'Componentes',benefits:'Benefícios'}[key]||key)+'</h4>'+(Array.isArray(value)?list(value):'<p>'+html(value)+'</p>')).join('')+'</details>';
  if(p.variants?.length)section+='<h3>Nuances e corretores do catálogo2025</h3>'+p.variants.map(group=>'<h4>'+html(group.group)+'</h4>'+list(group.variants)).join('');
 }
 const fieldKey={use:'use',actives:'actives',overview:'indication'}[detailTab];if(fieldKey&&p.fieldSources?.[fieldKey]){const source=p.fieldSources[fieldKey];section+='<p class="details-meta">Fonte desta orientação: <a href="'+html(safeUrl(source.url))+'" target="_blank" rel="noopener noreferrer">'+html(source.label)+'</a></p>';}
 $('product-detail').innerHTML=`<div class="dialog-head">${returnKit?`<button class="text-button" data-back-kit="${html(returnKit)}">← Voltar ao kit</button>`:'<span class="eyebrow">FICHA DE CONSULTA</span>'}<button class="icon-button" data-close="product-dialog" aria-label="Fechar ficha">×</button></div><div class="detail-body"><div class="detail-top"><div class="detail-photo">${photo(p,true)}${p.imageContext?`<small class="photo-context">${html(p.imageContext)}</small>`:''}</div><div><span class="eyebrow">${html(p.line)} · ${html(p.type)}</span><h2 id="detail-name">${html(p.name)}</h2><details class="reference-price"><summary>Preço público de referência</summary><div class="price">${money(p.price)}<small>${catalog.dateLabel}</small></div></details><p class="warning-label">${html(p.priceNote||'Valor sujeito a alterações e promoções no site oficial.')}</p><a class="source-link" href="${html(safeUrl(p.priceSource||p.url))}" target="_blank" rel="noopener noreferrer">Ver fonte do preço ↗</a><p></p><button class="button light small" data-favorite="${p.id}" aria-pressed="${favoriteOn}">${favoriteOn?'♥ Nos favoritos':'♡ Favoritar'}</button></div></div><div class="detail-tabs" role="group" aria-label="Seções da ficha">${tabs.map(([id,label])=>`<button data-tab="${id}" class="${id===detailTab?'active':''}" aria-pressed="${id===detailTab}">${label}</button>`).join('')}</div><section class="detail-section">${section}</section><div class="detail-foot">${p.sourceKind==='consultor'?'Cadastro informado pelo consultor; ficha oficial pendente.<br>':''}Fonte: <a class="source-link" href="${html(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">Ver página oficial ↗</a>${p.imageOrigin?`<br>Imagem: ${html(p.imageOrigin)}${Number.isInteger(p.imagePage)?' · página impressa '+p.imagePage:''}.`:""}<br>Consultado em ${catalog.dateLabel}. ${p.detailLevel!=='detailed'?'Campos não divulgados pela fonte estão identificados na ficha.':''}<br>Ferramenta pessoal do consultor; conteúdo técnico resumido a partir das fontes indicadas.</div></div>`;handleImages($('product-detail'));
 const note=$('product-note');if(note)note.addEventListener('input',()=>{personal.notes[p.id]=note.value;if(persist())$('note-state').textContent='Salvo neste aparelho.';});
}
function renderCompareTray(){const n=selected.size;$('compare-tray').hidden=!n;$('compare-count').textContent=`${n} de 3 selecionados`;$('open-compare').disabled=n<2;}
function renderComparison(){const products=catalog.products.filter(p=>selected.has(p.id));const rows=[['Preço público',p=>money(p.price)],['Linha',p=>p.line],['Indicação',p=>p.indication||'Não informada'],['Benefícios',p=>p.benefits?.join('; ')||'Não informados'],['Ativos',p=>p.actives?.join('; ')||'Não informados'],['Modo de uso',p=>p.use||'Não informado'],['Composição INCI',p=>p.inci||'Não publicada na fonte consultada']];$('comparison').innerHTML=`<div class="table-wrap"><table class="compare-table"><thead><tr><th scope="col">Comparação</th>${products.map(p=>`<th scope="col">${html(p.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,get])=>`<tr><th scope="row">${label}</th>${products.map(p=>`<td>${html(get(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('compare-dialog').showModal();}
async function offlineStatus(){if(!('serviceWorker'in navigator))return null;const registration=await navigator.serviceWorker.ready;const worker=registration.active;if(!worker)return null;return new Promise(resolve=>{const channel=new MessageChannel();const timer=setTimeout(()=>resolve(null),5000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data);};worker.postMessage({type:'STATUS',images:catalog.products.map(p=>p.imageUrl).filter(Boolean)},[channel.port2]);});}
function renderOffline(){const photos=catalog.products.filter(p=>p.imageUrl).length;$('extra-content').innerHTML=`<section class="offline-panel"><h3>Seu catálogo vai com você.</h3><p>Salve as fichas e as fotos antes de sair. A primeira abertura e a preparação para uso offline precisam de internet. Depois, abra o app neste mesmo navegador ou pelo ícone instalado.</p><div class="coverage">${html(catalog.coverageNote)}<br>${catalog.products.length} produtos cadastrados · ${catalog.products.filter(p=>p.detailLevel==='detailed').length} fichas técnicas revisadas · ${photos} fotos oficiais localizadas.</div><button id="download-offline" class="button dark">↓ Preparar catálogo e fotos offline</button><button id="check-update" class="button light">↻ Verificar atualização</button><p id="download-status" class="image-count" aria-live="polite">Consultando arquivos salvos…</p><progress id="download-progress" class="offline-progress" value="0" max="100" hidden></progress><div class="install-tip"><b>Instalar no Android</b><br>Abra o link no Chrome. Toque no menu ⋮ e escolha “Adicionar à tela inicial” ou “Instalar aplicativo”. Se o botão Instalar aparecer no topo, você também pode usá-lo.</div><p class="details-meta">Fotos não localizadas na fonte ficam identificadas. Se alguma imagem não baixar, tente novamente com internet. O catálogo salvo é uma cópia; preços não se atualizam sem conexão.</p><div class="storage-actions"><h3>Suas notas e favoritos</h3><p>Os dados pessoais ficam neste aparelho. Faça uma cópia antes de limpar os dados do navegador ou trocar de celular.</p><button class="button" id="export-personal">Exportar minhas anotações</button><label class="button" for="import-personal">Importar cópia</label><input id="import-personal" type="file" accept="application/json,.json" class="sr-only"></div></section>`;offlineStatus().then(s=>{const el=$('download-status');if(el)el.textContent=s?`${s.shellReady?'Catálogo salvo neste aparelho.':'Preparação do catálogo pendente.'} Fotos armazenadas: ${s.imagesCached} de ${photos}.`:'O modo offline será disponibilizado em uma conexão HTTPS compatível.';});}
async function downloadOffline(){if(!('serviceWorker'in navigator)){toast('Este navegador não oferece suporte ao catálogo offline. Use o Chrome no Android.');return;}if(!navigator.onLine){toast('Conecte-se à internet para preparar ou completar o catálogo.');return;}if(page!=='offline'){location.hash='offline';await new Promise(r=>setTimeout(r,60));}
 const button=$('download-offline');if(button)button.disabled=true;const bar=$('download-progress');if(bar)bar.hidden=false;
 try{const registration=await navigator.serviceWorker.ready;const images=[...new Set(catalog.products.map(p=>safeUrl(p.imageUrl)).filter(Boolean))];await new Promise((resolve,reject)=>{const channel=new MessageChannel();const timer=setTimeout(()=>reject(Error('O download demorou. Tente novamente; os arquivos já salvos serão aproveitados.')),180000);channel.port1.onmessage=e=>{const d=e.data;const el=$('download-status');if(el)el.textContent=d.message||`Fotos armazenadas: ${d.saved||0} de ${images.length}.`;if(bar)bar.value=d.total?Math.round(d.done/d.total*100):100;if(d.type==='DONE'){clearTimeout(timer);resolve(d);}if(d.type==='ERROR'){clearTimeout(timer);reject(Error(d.message));}};registration.active.postMessage({type:'DOWNLOAD',images},[channel.port2]);});await navigator.storage?.persist?.();toast('Preparação concluída. Confira a quantidade de fotos salvas antes de sair.');}catch(error){toast(error.message);const el=$('download-status');if(el)el.textContent=error.message;}finally{if(button)button.disabled=false;}
}
async function checkUpdate(){const b=$('check-update');if(b)b.disabled=true;try{const response=await fetch('catalog.json?refresh='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('Não foi possível consultar uma atualização.');const next=await response.json();if(!Array.isArray(next.products)||!next.products.length)throw Error('O catálogo recebido não é válido.');catalog=next;fillFilters();render();toast('Catálogo consultado. Salve novamente para levar a versão atual offline.');const reg=await navigator.serviceWorker?.getRegistration();await reg?.update();}catch{toast('Sem atualização disponível agora. Seu catálogo salvo foi preservado.');}finally{if(b)b.disabled=false;}}
function exportPersonal(){const payload={version:1,exportedAt:new Date().toISOString(),favorites:personal.favorites,notes:personal.notes,study:personal.study};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='minhas-notas-dal-cotone.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function importPersonal(file){try{if(!file||file.size>1024*1024)throw Error();const p=JSON.parse(await file.text());if(p.version!==1||!Array.isArray(p.favorites)||!p.notes||typeof p.notes!=='object'||Array.isArray(p.notes))throw Error();const valid=new Set(catalog.products.map(p=>p.id));const notes={};for(const [id,note]of Object.entries(p.notes)){if(valid.has(id)&&typeof note==='string'&&note.length<=10000)notes[id]=note;}const study={};if(p.study&&typeof p.study==='object'){const allowed=new Set(makeDeck(catalog.products).map(c=>c.id));for(const [id,value]of Object.entries(p.study))if(allowed.has(id)&&['known','review'].includes(value))study[id]=value;}personal={favorites:[...new Set(p.favorites.filter(id=>valid.has(id)))],notes,study};if(persist()){render();toast('Anotações e favoritos importados para este aparelho.');}}catch{toast('Não foi possível importar. Use um arquivo de cópia exportado por este aplicativo.');}}
function fillFilters(){for(const [id,key,label]of [['line-filter','line','Todas as linhas'],['type-filter','type','Todos os tipos']]){$(id).innerHTML=`<option value="">${label}</option>`+[...new Set(catalog.products.map(p=>p[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(v=>`<option value="${html(v)}">${html(v)}</option>`).join('');}$('category-filter').innerHTML='<option value="">Todos os tratamentos</option>'+catalog.categories.map(c=>`<option value="${html(c.name)}">${html(c.name)}</option>`).join('');}
function connection(){const online=navigator.onLine;$('connection').textContent=online?'● Online':'● Offline';$('connection').style.color=online?'#678060':'#a67b51';$('sidebar-status').textContent=online?'Conectado para atualizar':'Consulta sem internet';}
document.addEventListener('click',e=>{if(e.target.closest('#clear-facets')){selectedHairTypes.clear();selectedProductTypes.clear();renderCards();return;}const backKit=e.target.closest('[data-back-kit]');if(backKit){openProduct(backKit.dataset.backKit);detailTab='kit';renderDetail();return;}const copy=e.target.closest('[data-copy-script]');if(copy){const text=$(copy.dataset.copyScript)?.innerText||'';if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>toast('Texto copiado. Adapte à sua conversa.')).catch(()=>toast('Selecione o texto para copiar.'));else toast('Selecione o texto para copiar.');return;}const productLine=e.target.closest('[data-product-line]');if(productLine){$('product-dialog').close();location.hash='linhas/'+encodeURIComponent(productLine.dataset.productLine);return;}if(e.target.closest('#copy-pitch')){navigator.clipboard?.writeText(catalog.company.pitch).then(()=>toast('Roteiro copiado.')).catch(()=>toast('Selecione o texto para copiar o roteiro.'));return;}if(e.target.closest('#reveal-study')){studyRevealed=true;renderStudy();return;}if(e.target.closest('#next-study')){const deck=makeDeck(catalog.products,{line,category});studyIndex=(studyIndex+1)%deck.length;studyRevealed=false;renderStudy();return;}const mark=e.target.closest('[data-study-mark]');if(mark){const deck=makeDeck(catalog.products,{line,category});if(deck[studyIndex])personal.study[deck[studyIndex].id]=mark.dataset.studyMark;persist();studyIndex=(studyIndex+1)%deck.length;studyRevealed=false;renderStudy();return;}const close=e.target.closest('[data-close]');if(close){$(close.dataset.close).close();return;}const f=e.target.closest('[data-favorite]');if(f){favorite(f.dataset.favorite);return;}const n=e.target.closest('[data-need]');if(n){need=n.dataset.need;renderCards();return;}const g=e.target.closest('[data-guide]');if(g){need=g.dataset.guide;query='';line='';type='';$('line-filter').value='';$('type-filter').value='';location.hash='pesquisa';return;}const o=e.target.closest('[data-open]');if(o){openProduct(o.dataset.open,o.dataset.fromKit||null);return;}const tab=e.target.closest('[data-tab]');if(tab){detailTab=tab.dataset.tab;renderDetail();return;}const nav=e.target.closest('[data-route]');if(nav){location.hash=nav.dataset.route;return;}if(e.target.closest('[data-reset]')||e.target.closest('#reset-filters'))reset();if(e.target.closest('#download-top')||e.target.closest('#download-offline'))downloadOffline();if(e.target.closest('#check-update'))checkUpdate();if(e.target.closest('#export-personal'))exportPersonal();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();location.hash='pesquisa';$('search').focus();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.product-photo')){e.preventDefault();openProduct(e.target.dataset.open);}});
$('search-form').addEventListener('submit',e=>e.preventDefault());$('search').addEventListener('input',e=>{query=e.target.value;renderCards();});$('clear-search').onclick=()=>{query='';renderCards();$('search').focus();};$('line-filter').onchange=e=>{line=e.target.value;renderCards();};$('type-filter').onchange=e=>{type=e.target.value;renderCards();};$('sort').onchange=e=>{sort=e.target.value;renderCards();};$('category-filter').onchange=e=>{category=e.target.value;renderCards();};
document.addEventListener('change',e=>{if(e.target.id==='study-line'){location.hash='estudar/'+encodeURIComponent(e.target.value);return;}if(e.target.matches('[data-compare]')){const id=e.target.dataset.compare;if(e.target.checked){if(selected.size===3){e.target.checked=false;toast('Compare até 3 produtos por vez.');return;}selected.add(id);}else selected.delete(id);renderCompareTray();}if(e.target.id==='import-personal')importPersonal(e.target.files[0]);});
$('open-compare').onclick=renderComparison;$('clear-compare').onclick=()=>{selected.clear();renderCards();};window.addEventListener('hashchange',route);window.addEventListener('online',connection);window.addEventListener('offline',connection);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('install').hidden=true;};
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
async function init(){connection();try{const response=await fetch('catalog.json',{cache:'no-store'});if(!response.ok)throw Error();catalog=await response.json();if(!Array.isArray(catalog.products)||!catalog.products.length)throw Error();fillFilters();route();const featured=catalog.products.find(p=>normalize(p.name).includes('banana')&&p.imageUrl)||catalog.products.find(p=>p.imageUrl);if(featured){$('hero-image').src=featured.imageUrl;$('hero-image').alt=featured.name;$('hero-image').hidden=false;$('hero-image').onerror=()=>{$('hero-image').hidden=true;};}$('catalog-date').textContent=`Fontes oficiais · consulta em ${catalog.dateLabel}`;if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.register('sw.js',{updateViaCache:'none'});await registration.update();await navigator.serviceWorker.ready;}}catch(error){$('products').innerHTML='<div class="network-error"><h2>Seu catálogo ainda não carregou</h2><p>Conecte-se à internet na primeira abertura e tente novamente.</p><button class="button" onclick="location.reload()">Tentar novamente</button></div>';$('page-subtitle').textContent='Não foi possível carregar as fichas.';}}
init();

document.addEventListener('change',event=>{const input=event.target;if(input.matches('[data-hair-type],[data-product-type],[data-situation]')){const group=input.hasAttribute('data-hair-type')?selectedHairTypes:input.hasAttribute('data-product-type')?selectedProductTypes:selectedSituations;const value=input.dataset.hairType||input.dataset.productType||input.dataset.situation;input.checked?group.add(value):group.delete(value);if(input.hasAttribute('data-situation')){guideManual=true;saveGuideState();}const attribute=input.hasAttribute('data-hair-type')?'data-hair-type':input.hasAttribute('data-product-type')?'data-product-type':'data-situation';renderCards();[...document.querySelectorAll('['+attribute+']')].find(node=>node.getAttribute(attribute)===value)?.focus();}if(input.id==='outcome-filter'){selectedGoal=input.value;saveGuideState();renderCards();}});
document.addEventListener('submit',event=>{if(event.target.id!=='situation-form')return;event.preventDefault();guideDescription=$('situation-description').value.slice(0,600);selectedSituations=new Set(inferSituations(guideDescription));guideManual=false;saveGuideState();renderGuide();renderCards();});
